param([Parameter(Mandatory=$true)][string]$ReferencePath,[Parameter(Mandatory=$true)][string]$BackgroundPath,[Parameter(Mandatory=$true)][string]$TitlePath,[Parameter(Mandatory=$true)][string]$MousePath)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing.Common,System.Drawing.Primitives,System.Runtime,System.Collections,System.Runtime.InteropServices,System.Private.Windows.GdiPlus,System.Private.Windows.Core,System.Console,System.Text.Json -TypeDefinition @"
using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Collections.Generic;using System.Text.Json;
public class MainMenuAssetImport {
 class Raster{public int W,H;public byte[] Data;public Raster(string file){using(var b=new Bitmap(file)){W=b.Width;H=b.Height;int pixel=Image.GetPixelFormatSize(b.PixelFormat)/8;var bits=b.LockBits(new Rectangle(0,0,W,H),ImageLockMode.ReadOnly,b.PixelFormat);var raw=new byte[Math.Abs(bits.Stride)*H];System.Runtime.InteropServices.Marshal.Copy(bits.Scan0,raw,0,raw.Length);b.UnlockBits(bits);Data=new byte[W*H*4];for(int y=0;y<H;y++)for(int x=0;x<W;x++){int src=y*Math.Abs(bits.Stride)+x*pixel,at=(y*W+x)*4;Data[at]=raw[src];Data[at+1]=raw[src+1];Data[at+2]=raw[src+2];Data[at+3]=pixel==4?raw[src+3]:(byte)255;}}}}
 static void Save(string file,byte[] data,int w,int h){using(var b=new Bitmap(w,h,PixelFormat.Format32bppArgb)){var bits=b.LockBits(new Rectangle(0,0,w,h),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);System.Runtime.InteropServices.Marshal.Copy(data,0,bits.Scan0,data.Length);b.UnlockBits(bits);b.Save(file);}}
 static byte[] Crop(Raster r,Rectangle box){var a=new byte[box.Width*box.Height*4];for(int y=0;y<box.Height;y++)Array.Copy(r.Data,((y+box.Y)*r.W+box.X)*4,a,y*box.Width*4,box.Width*4);return a;}
 static Rectangle Bounds(Raster r,Rectangle box){int l=box.Right,t=box.Bottom,rr=-1,b=-1;for(int y=box.Y;y<box.Bottom;y++)for(int x=box.X;x<box.Right;x++)if(r.Data[(y*r.W+x)*4+3]>0){l=Math.Min(l,x);t=Math.Min(t,y);rr=Math.Max(rr,x);b=Math.Max(b,y);}return rr<0?new Rectangle(box.X,box.Y,1,1):new Rectangle(l,t,rr-l+1,b-t+1);}
 public static void Build(string output,string reference,string background,string title,string mouse){Directory.CreateDirectory(output);string originals=Path.Combine(output,"originals");Directory.CreateDirectory(originals);File.WriteAllText(Path.Combine(originals,".gdignore"),"");foreach(var pair in new[]{new[]{reference,"reference.png"},new[]{background,"background.png"},new[]{title,"title.png"},new[]{mouse,"mouse.png"}}){string dest=Path.Combine(originals,pair[1]);if(!File.Exists(dest))File.Copy(pair[0],dest);}
 File.Copy(background,Path.Combine(output,"background.png"),true);var bg=new Raster(background);
 var letters=new List<object>();var tx=new Raster(title);int[][] cuts={new[]{0,299,482,703,979,1174,1372,1672},new[]{0,732,935,1672},new[]{0,250,436,647,831,1017,1214,1436,1672}};int[] yy={0,333,559,941};string[] words={"FLOWERS","FOR","ALGERNON"};Directory.CreateDirectory(Path.Combine(output,"letters"));var reassembled=new byte[tx.Data.Length];int index=0;
 for(int row=0;row<3;row++)for(int col=0;col<words[row].Length;col++){var cell=new Rectangle(cuts[row][col],yy[row],cuts[row][col+1]-cuts[row][col],yy[row+1]-yy[row]);var bounds=Bounds(tx,cell);var pixels=Crop(tx,bounds);string file="letters/letter_"+index.ToString("00")+".png";Save(Path.Combine(output,file),pixels,bounds.Width,bounds.Height);for(int y=0;y<bounds.Height;y++)Array.Copy(pixels,y*bounds.Width*4,reassembled,((y+bounds.Y)*tx.W+bounds.X)*4,bounds.Width*4);letters.Add(new {index=index,row=row,letter=words[row].Substring(col,1),file=file,rect=new[]{bounds.X,bounds.Y,bounds.Width,bounds.Height}});index++;}
 int errors=0;for(int i=0;i<tx.Data.Length;i+=4)if(tx.Data[i+3]>0&&(tx.Data[i]!=reassembled[i]||tx.Data[i+1]!=reassembled[i+1]||tx.Data[i+2]!=reassembled[i+2]||tx.Data[i+3]!=reassembled[i+3]))errors++;if(errors!=0)throw new Exception("Title reassembly mismatch "+errors);
 var rf=new Raster(reference);var menu=new List<object>();var boxes=new[]{new Rectangle(3529,2290,796,185),new Rectangle(3532,2716,792,185),new Rectangle(3535,3194,790,172)};string[] labels={"开始游戏","制作名单","回到桌面"};for(int n=0;n<3;n++){var box=boxes[n];var data=new byte[box.Width*box.Height*4];for(int y=0;y<box.Height;y++)for(int x=0;x<box.Width;x++){int at=((y+box.Y)*rf.W+x+box.X)*4,at2=(y*box.Width+x)*4;double ratio=1;for(int c=0;c<3;c++)ratio=Math.Min(ratio,(double)rf.Data[at+c]/Math.Max(1,(int)bg.Data[at+c]));double a=Math.Clamp(1-ratio,0,1);data[at2+3]=a<0.015?(byte)0:(byte)Math.Round(a*255);}string file="menu_"+n+".png";Save(Path.Combine(output,file),data,box.Width,box.Height);menu.Add(new {label=labels[n],file=file,rect=new[]{box.X,box.Y,box.Width,box.Height}});}
 var ms=new Raster(mouse);var mb=Bounds(ms,new Rectangle(0,0,ms.W,ms.H));Save(Path.Combine(output,"mouse.png"),Crop(ms,mb),mb.Width,mb.Height);var metadata=new{background_size=new[]{bg.W,bg.H},title_size=new[]{tx.W,tx.H},title_reference_origin=new[]{1845.0,72.0},title_reference_scale=2.432,title_ink_rect=new[]{60.0,124.0,1552.0,648.0},letters=letters,menus=menu,mouse_rect=new[]{mb.X,mb.Y,mb.Width,mb.Height},mouse_nose=new[]{512-mb.X,237-mb.Y},mouse_body=new[]{502.0-mb.X,741.5-mb.Y},title_reassembly_mismatches=errors};File.WriteAllText(Path.Combine(output,"layout.json"),JsonSerializer.Serialize(metadata,new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(output,"layout.gd"),"extends RefCounted\nconst DATA := "+JsonSerializer.Serialize(metadata,new JsonSerializerOptions{WriteIndented=true})+"\n");Console.WriteLine("TITLE 18 letters; reassembled nontransparent pixels match exactly. Mouse crop="+mb+". Original images preserved.");}
}
"@
[MainMenuAssetImport]::Build((Join-Path $PSScriptRoot '../godot/modules/main_menu/assets'),$ReferencePath,$BackgroundPath,$TitlePath,$MousePath)
